import java.util.*;class Fraction{int num,den;Fraction(int n,int d){if(d==0)throw new IllegalArgumentException("Denominator cannot be zero");int g=gcd(Math.abs(n),Math.abs(d));num=n/g;den=d/g;if(den<0){num=-num;den=-den;}}static int gcd(int a,int b){return b==0?a:gcd(b,a%b);}public String toString(){return num+"/"+den;}public boolean equals(Object o){return o instanceof Fraction f&&num==f.num&&den==f.den;}public int hashCode(){return Objects.hash(num,den);}}public class FractionDriver{public static void main(String[]z){Fraction a=new Fraction(2,4),b=new Fraction(1,2),c=new Fraction(3,6);System.out.println(a+" equals "+b+": "+a.equals(b)+", all="+a.equals(c));}}
